def count_no_of_ways(n: int, k: int) -> int:
    # Base case: 1 post
    if n == 1:
        return 1

    # Base case: 2 posts
    if n == 2:
        return k

    # Recursive case: n > 2
    ways = [0] * (k + 1)
    ways[0] = 1
    ways[1] = 1

    for i in range(2, n):
        for j in range(k):
            if i - j < 0:
                break
            ways[i] += ways[i - j]

    return ways[n - 1]
